class Solution {
public:
    int maximumMatchingIndices(vector<int>& nums1, vector<int>& nums2) {
        int n = nums1.size();
        int maxMatches = 0;
        for (int shift = 0; shift < n; ++shift) {
            int current = 0;
            for (int i = 0; i < n; ++i) {
                if (nums1[(i - shift + n) % n] == nums2[i]) {
                    current++;
                }
            }
            maxMatches = max(maxMatches, current);
        }
        return maxMatches;
    }
};

