var maximumMatchingIndices = function(nums1, nums2) {
    const n = nums1.length;
    let maxMatches = 0;
    for (let shift = 0; shift < n; ++shift) {
        let current = 0;
        for (let i = 0; i < n; ++i) {
            if (nums1[(i - shift + n) % n] === nums2[i]) {
                current++;
            }
        }
        if (current > maxMatches) {
            maxMatches = current;
        }
    }
    return maxMatches;
};
